export type SubjectAuthorityCategory =
  | "ADJACENT_VARIANT"
  | "AMBIGUOUS_MULTI_SUBJECT"
  | "CAUSAL_SAME_ENDPOINT"
  | "CAUSAL_WRONG_COUNTERPART"
  | "DIFFERENT_COMPANY"
  | "DIFFERENT_COUNTRY"
  | "DIFFERENT_MATURITY"
  | "DIFFERENT_SHARE_CLASS"
  | "EXACT_SAME_SUBJECT"
  | "NORMALIZED_SAME_SUBJECT"
  | "NO_REPOSITORY_SUBJECT"
  | "OPERATION_MISMATCH"
  | "RELATED_INDEX_FAMILY"
  | "SIBLING_SERIES";

export interface SubjectAuthorityCase {
  id: string;
  language: "EN" | "KO";
  query: string;
  /** Every stored subject name bearing on the case, distractors included. */
  repositorySubjects: string[];
  /** The one the planner points at; `""` when nothing stored is about the question. */
  targetSubject: string;
  targetKind: "SERIES_FACT" | "SERIES_CALCULATION" | "CAUSAL_EDGE";
  category: SubjectAuthorityCategory;
  expected: "ANSWERED" | "NOT_A_CANDIDATE" | "AMBIGUOUS_NO_PLANNER" | "NO_SUBJECT_NO_PLANNER";
  rationale: string;
}

